    roundtrip(formatInfo, testImage, "indexable", imageExact);
}

@ParameterizedTest
@MethodSource("data")
public void testNullParametersRoundtrip(final FormatInfo formatInfo) throws Exception {
    final BufferedImage testImage = TestImages.createFullColorImage(1, 1);
    final byte[] temp1;
    try (ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream()) {
        Imaging.writeImage(testImage, byteArrayOutputStream, formatInfo.format);
        temp1 = byteArrayOutputStream.toByteArray();
    }
    final String fileName = "nullParameters." + formatInfo.format.getDefaultExtension();
    Imaging.getImageInfo(new ByteArrayInputStream(temp1), fileName);
    Imaging.getImageSize(new ByteArrayInputStream(temp1), fileName);
    Imaging.getMetadata(new ByteArrayInputStream(temp1), fileName);
    Imaging.getIccProfile(new ByteArrayInputStream(temp1), fileName);
    final BufferedImage imageRead = Imaging.getBufferedImage(new ByteArrayInputStream(temp1), fileName);
    assertNotNull(imageRead);
}

@ParameterizedTest
@MethodSource
public void testPixelDensityRoundtrip(final FormatInfo formatInfo) throws Exception {
    final BufferedImage testImage = TestImages.createFullColorImage(2, 2);
    final TiffImagingParameters params = new TiffImagingParameters();
    final PixelDensity pixelDensity = PixelDensity.createFromPixelsPerInch(75, 150);
    params.setPixelDensity(pixelDensity);
    final TiffImageParser tiffImageParser = new TiffImageParser();
    final ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    tiffImageParser.writeImage(testImage, byteArrayOutputStream, params);
    final ImageInfo imageInfo = Imaging.getImageInfo(byteArrayOutputStream.toByteArray());
    if (imageInfo != null) {
        final int xReadDPI = imageInfo.getPhysicalWidthDpi();
        final int yReadDPI = imageInfo.getPhysicalHeightDpi();
        // allow a 5% margin of error in storage and conversion
        assertTrue(Math.abs((xReadDPI - pixelDensity.horizontalDensityInches()) / pixelDensity.horizontalDensityInches()) <= 0.05);
        assertTrue(Math.abs((yReadDPI - pixelDensity.verticalDensityInches()) / pixelDensity.verticalDensityInches()) <= 0.05);
    }
}
